"use strict";

const CONFIG={apiUrl:"https://script.google.com/macros/s/AKfycbwQecbU4ucCeniusUi-9Dj5uyDpXkfb95H9eyD4HsJatrMZ0PhTZoVAjAc5JHObocBUlg/exec",demoCode:"DEMO01",questionCount:10,storageKey:"dragonCoasterRankingsV1"};
const CHARACTERS=[
 {id:"panda",emoji:"🐼",name:"판다 탐험가",desc:"느긋하지만 용감해요"},{id:"fox",emoji:"🦊",name:"여우 마법사",desc:"반짝이는 지혜의 친구"},{id:"rabbit",emoji:"🐰",name:"토끼 학생",desc:"호기심이 가득해요"},{id:"tiger",emoji:"🐯",name:"호랑이 무술가",desc:"도전을 즐기는 친구"},{id:"cat",emoji:"🐱",name:"고양이 요리사",desc:"맛있는 단어를 찾아요"},{id:"monkey",emoji:"🐵",name:"원숭이 발명가",desc:"기발한 생각이 넘쳐요"},{id:"dog",emoji:"🐶",name:"강아지 우주인",desc:"별처럼 씩씩해요"},{id:"dragon",emoji:"🐲",name:"꼬마 청룡",desc:"청룡열차의 단짝"}
];
const DEMO_QUESTIONS=[
 {id:"q1",type:"단어 뜻",question:"苹果의 뜻은?",text:"苹果",pinyin:"píngguǒ",choices:["사과","포도","수박","바나나"],answer:0,explanation:"苹果는 ‘사과’라는 뜻이에요."},
 {id:"q2",type:"중국어 선택",question:"‘학교’에 해당하는 단어는?",text:"学校",pinyin:"xuéxiào",choices:["老师","学校","朋友","学生"],answer:1,explanation:"学校는 학교를 뜻해요."},
 {id:"q3",type:"병음 선택",question:"朋友의 올바른 병음은?",text:"朋友",pinyin:"péngyou",choices:["píngguǒ","péngyou","xuéxiào","lǎoshī"],answer:1,explanation:"朋友 péngyou는 친구예요."},
 {id:"q4",type:"문장 뜻",question:"我喜欢学习中文。의 뜻은?",text:"我喜欢学习中文。",pinyin:"wǒ xǐhuan xuéxí Zhōngwén",choices:["나는 중국어 공부를 좋아한다","나는 학교에 간다","나는 친구를 만난다","나는 사과를 먹는다"],answer:0,explanation:"喜欢는 ‘좋아하다’, 学习는 ‘공부하다’예요."},
 {id:"q5",type:"빈칸",question:"我___学生。빈칸에 알맞은 말은?",text:"我是学生。",pinyin:"wǒ shì xuésheng",choices:["吃","去","是","有"],answer:2,explanation:"是는 ‘~이다’라는 뜻이에요."},
 {id:"q6",type:"단어 뜻",question:"老师의 뜻은?",text:"老师",pinyin:"lǎoshī",choices:["학생","선생님","부모님","친구"],answer:1,explanation:"老师는 선생님이에요."},
 {id:"q7",type:"중국어 선택",question:"‘물’에 해당하는 단어는?",text:"水",pinyin:"shuǐ",choices:["火","茶","饭","水"],answer:3,explanation:"水는 물을 뜻해요."},
 {id:"q8",type:"단어 뜻",question:"今天의 뜻은?",text:"今天",pinyin:"jīntiān",choices:["내일","어제","오늘","매일"],answer:2,explanation:"今天은 오늘이에요."},
 {id:"q9",type:"병음 선택",question:"谢谢의 올바른 병음은?",text:"谢谢",pinyin:"xièxie",choices:["xièxie","nǐ hǎo","zàijiàn","duìbuqǐ"],answer:0,explanation:"谢谢 xièxie는 ‘감사합니다’예요."},
 {id:"q10",type:"문장 뜻",question:"你叫什么名字？의 뜻은?",text:"你叫什么名字？",pinyin:"nǐ jiào shénme míngzi",choices:["몇 살입니까?","어디에 갑니까?","이름이 무엇입니까?","무엇을 먹습니까?"],answer:2,explanation:"叫什么名字는 이름을 묻는 표현이에요."}
];

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={screen:"start",classCode:"DEMO01",classTitle:"청룡열차 체험 수업",studentName:"",character:null,questions:[],index:0,answers:[],correct:0,combo:0,wrongStreak:0,bestCombo:0,currentSpeed:32,startTime:0,elapsed:0,timer:null,sessionId:null,sound:true,lastRankId:null,locked:false};

function show(name){$$(`.screen`).forEach(x=>x.classList.remove("active"));$(`#${name}Screen`).classList.add("active");state.screen=name;}
function escapeText(v){return String(v??"").replace(/[<>]/g,"");}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function formatTime(ms){const t=Math.max(0,ms),m=Math.floor(t/60000),s=Math.floor(t%60000/1000),d=Math.floor(t%1000/100);return `${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}.${d}`}
function beep(freq=440,duration=.12,type="sine"){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext,c=new C(),o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.12,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration)}catch{}}
function speak(){const q=state.questions[state.index];if(!q||!state.sound||!window.speechSynthesis)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(q.text||q.question);u.lang="zh-CN";u.rate=.82;window.speechSynthesis.speak(u)}

async function api(action,payload={}){if(!CONFIG.apiUrl)throw new Error("DEMO_MODE");const method=action.startsWith("get")?"GET":"POST";const url=method==="GET"?`${CONFIG.apiUrl}?action=${encodeURIComponent(action)}&${new URLSearchParams(payload)}`:CONFIG.apiUrl;const options={method,redirect:"follow"};if(method==="POST"){options.headers={"Content-Type":"text/plain;charset=utf-8"};options.body=JSON.stringify({action,...payload})}const res=await fetch(url,options);const json=await res.json();if(!json.success)throw new Error(json.error?.message||"요청을 처리하지 못했습니다.");return json.data}

async function enterClass(){const code=escapeText($("#classCode").value).trim().toUpperCase();if(code.length<4){$("#codeHint").textContent="수업 코드를 확인해주세요.";return}$("#enterBtn").disabled=true;$("#codeHint").textContent="수업을 확인하고 있어요…";try{let data;if(code===CONFIG.demoCode||!CONFIG.apiUrl){if(code!==CONFIG.demoCode)throw new Error("현재는 DEMO01 수업으로 체험할 수 있어요.");data={code,title:"청룡열차 체험 수업"}}else data=await api("getClass",{code});state.classCode=code;state.classTitle=data.title;show("profile")}catch(e){$("#codeHint").textContent=e.message}finally{$("#enterBtn").disabled=false}}
function renderCharacters(){const saved=localStorage.getItem("dragonCoasterCharacter");$("#characterGrid").innerHTML=CHARACTERS.map(c=>`<button class="character-card ${saved===c.id?"selected":""}" data-id="${c.id}"><span class="avatar">${c.emoji}</span><strong>${c.name}</strong><small>${c.desc}</small></button>`).join("");if(saved){state.character=CHARACTERS.find(c=>c.id===saved);$("#startGameBtn").disabled=!state.character}}
function chooseCharacter(id){state.character=CHARACTERS.find(c=>c.id===id);localStorage.setItem("dragonCoasterCharacter",id);$$(`.character-card`).forEach(x=>x.classList.toggle("selected",x.dataset.id===id));$("#startGameBtn").disabled=false;beep(620,.08)}

async function startGame(){state.questions=[];state.index=0;state.answers=[];state.correct=0;state.combo=0;state.wrongStreak=0;state.bestCombo=0;state.currentSpeed=32;state.elapsed=0;state.locked=false;try{if(state.classCode===CONFIG.demoCode||!CONFIG.apiUrl){state.questions=shuffle(DEMO_QUESTIONS).slice(0,CONFIG.questionCount);state.sessionId=`demo-${Date.now()}`}else{const d=await api("startSession",{classCode:state.classCode,studentName:state.studentName,characterId:state.character.id});state.questions=d.questions;state.sessionId=d.sessionId}}catch(e){alert(`게임을 시작하지 못했습니다: ${e.message}`);return}beginRide()}
function beginRide(){show("game");$("#riderAvatar").textContent=state.character.emoji;setRideMode("cruise");setSpeed(32,"주행 시작","cruise");$("#quizCard").classList.add("hidden");let count=3;$("#feedbackBurst").textContent=count;$("#feedbackBurst").classList.add("show");const countdown=setInterval(()=>{count--;$("#feedbackBurst").classList.remove("show");void $("#feedbackBurst").offsetWidth;if(count>0){$("#feedbackBurst").textContent=count;$("#feedbackBurst").classList.add("show")}else{clearInterval(countdown);$("#feedbackBurst").textContent="출발!";$("#feedbackBurst").classList.add("show");state.startTime=performance.now();state.timer=setInterval(updateTimer,50);setTimeout(showQuestion,700)}},700)}
function updateTimer(){state.elapsed=performance.now()-state.startTime;$("#timerText").textContent=formatTime(state.elapsed)}
function showQuestion(){state.locked=false;const q=state.questions[state.index];setRideMode("cruise");setSpeed(50,"퀴즈 안정 주행","cruise");$("#progressText").textContent=`${state.index+1} / ${state.questions.length}`;$("#progressFill").style.width=`${state.index/state.questions.length*100}%`;$("#comboText").textContent=state.combo;$("#quizType").textContent=q.type;$("#questionText").textContent=q.question;$("#pinyinText").textContent="";$("#explanation").textContent="열차가 시속 50km로 안정 주행 중입니다. 정답을 골라주세요.";$("#answers").innerHTML=q.choices.map((c,i)=>`<button class="answer-btn" data-index="${i}"><b>${i+1}</b> ${escapeText(c)}</button>`).join("");$("#quizCard").classList.remove("hidden");}
async function answerQuestion(index){if(state.locked)return;state.locked=true;const q=state.questions[state.index];$$(`.answer-btn`).forEach(b=>b.disabled=true);let correct,correctIndex=q.answer,serverExplanation=q.explanation;try{if(state.classCode===CONFIG.demoCode||!CONFIG.apiUrl){correct=index===q.answer}else{const checked=await api("checkAnswer",{sessionId:state.sessionId,questionId:q.id,choiceIndex:index});correct=checked.correct;correctIndex=checked.correctIndex;serverExplanation=checked.explanation}}catch(e){state.locked=false;$$(`.answer-btn`).forEach(b=>b.disabled=false);$("#explanation").textContent=`답을 확인하지 못했어요. 다시 선택해주세요. (${e.message})`;return}state.answers.push({questionId:q.id,choiceIndex:index,correct,correctText:q.choices[correctIndex]});$$(`.answer-btn`).forEach((b,i)=>{if(i===correctIndex)b.classList.add("correct");if(i===index&&!correct)b.classList.add("wrong")});$("#pinyinText").textContent=q.pinyin||"";$("#explanation").textContent=serverExplanation||`정답: ${q.choices[correctIndex]}`;let delay;if(correct){state.correct++;state.combo++;state.wrongStreak=0;state.bestCombo=Math.max(state.bestCombo,state.combo);const speed=Math.min(180,88+(state.combo-1)*15),message=state.combo>1?`정답! ${state.combo}연속 가속 하강!`:"정답! 가속하며 하강!";rideEffect("downhill",message,speed,760,`${state.combo}연속 하강 가속`);delay=Math.max(1150,2100-(state.combo-1)*180)}else{state.combo=0;state.wrongStreak++;const speed=Math.max(5,22-(state.wrongStreak-1)*5),message=state.wrongStreak>1?`오답! ${state.wrongStreak}연속 상승 감속!`:"아쉬워요! 감속하며 상승!";rideEffect("uphill",message,speed,190,`${state.wrongStreak}연속 상승 감속`);delay=Math.min(4300,2700+(state.wrongStreak-1)*350)}$("#comboText").textContent=state.combo;setTimeout(nextQuestion,delay)}
function setSpeed(speed,label,mode){state.currentSpeed=Math.round(speed);$("#speedText").textContent=state.currentSpeed;$("#speedGaugeValue").textContent=state.currentSpeed;$("#streakLabel").textContent=label;const gauge=$("#speedGauge");gauge.className=`speed-gauge ${mode==="boost"?"boost":mode==="brake"?"brake":""}`;const angle=-55+Math.min(1,state.currentSpeed/180)*110;$("#speedNeedle").parentElement.style.transform=`translateX(-100%) rotate(${angle}deg)`;const duration=Math.max(.16,2.15-state.currentSpeed/88);$("#rideScene").style.setProperty("--track-speed",`${duration.toFixed(2)}s`)}
function setRideMode(mode){$("#rideScene").className=`ride-scene ${mode}${document.querySelector(".coaster-canvas")?" webgl-active":""}`}
function rideEffect(kind,message,speed,tone,label){setRideMode(kind);setSpeed(speed,label,kind==="downhill"?"boost":"brake");$("#feedbackBurst").textContent=message;$("#feedbackBurst").classList.remove("show");void $("#feedbackBurst").offsetWidth;$("#feedbackBurst").classList.add("show");beep(tone,.22,kind==="downhill"?"triangle":"sawtooth")}
function nextQuestion(){state.index++;$("#quizCard").classList.add("hidden");if(state.index>=state.questions.length){finishGame();return}setRideMode("cruise");const cruise=state.combo>0?Math.min(105,42+state.combo*8):Math.max(18,38-state.wrongStreak*5);setSpeed(cruise,state.combo>1?`${state.combo}연속 보너스 유지`:state.wrongStreak>1?`${state.wrongStreak}연속 감속 유지`:"다음 구간","cruise");setTimeout(showQuestion,900)}
function finishGame(){clearInterval(state.timer);state.elapsed=performance.now()-state.startTime;$("#progressFill").style.width="100%";setRideMode("downhill");const perfect=state.correct===state.questions.length;setTimeout(()=>perfect?playAscensionScene(showResult):showResult(),900)}
function playAscensionScene(done){const scene=$("#ascensionScene");$("#ascensionAvatar").textContent=state.character.emoji;scene.classList.add("show");scene.setAttribute("aria-hidden","false");beep(988,.55,"triangle");setTimeout(()=>{scene.classList.remove("show");scene.setAttribute("aria-hidden","true");done()},3600)}
function showResult(){show("result");$("#resultAvatar").textContent=state.character.emoji;$("#finalTime").textContent=formatTime(state.elapsed);$("#correctStat").textContent=`${state.correct}/${state.questions.length}`;$("#accuracyStat").textContent=`${Math.round(state.correct/state.questions.length*100)}%`;$("#bestComboStat").textContent=state.bestCombo;const misses=state.questions.map((q,i)=>({q,a:state.answers[i]})).filter(x=>x.a&&!x.a.correct);const seen=new Set();const cards=misses.filter(x=>{const k=x.q.text;if(seen.has(k))return false;seen.add(k);return true});$("#mistakeBox").innerHTML=cards.length?`<b class="mistake-title">다시 볼 단어 ${cards.length}개</b><div class="word-cards">${cards.map(({q,a})=>{const L=q.text.length,ko=q.explanation||a.correctText||"";return `<div class="word-card"><div class="wc-zh" style="font-size:${L<=4?46:L<=8?34:L<=14?26:22}px">${escapeText(q.text)}</div><div class="wc-py">${escapeText(q.pinyin||"")}</div><div class="wc-ko" style="font-size:${ko.length>30?14:17}px">${escapeText(ko)}</div></div>`}).join("")}</div>`:"<b>완벽해요! 모든 문제를 맞혔어요.</b>";$("#saveResultBtn").disabled=false;$("#saveStatus").textContent="";beep(880,.3,"triangle")}

function localRankings(){try{return JSON.parse(localStorage.getItem(CONFIG.storageKey)||"[]")}catch{return[]}}
function saveLocalResult(){const row={id:crypto.randomUUID?.()||String(Date.now()),classCode:state.classCode,name:state.studentName,characterId:state.character.id,character:state.character.emoji,timeMs:Math.round(state.elapsed),correct:state.correct,total:state.questions.length,accuracy:Math.round(state.correct/state.questions.length*100),bestCombo:state.bestCombo,createdAt:new Date().toISOString()};const rows=localRankings();rows.push(row);localStorage.setItem(CONFIG.storageKey,JSON.stringify(rows.slice(-100)));state.lastRankId=row.id;return row}
async function saveResult(){if($("#saveResultBtn").disabled)return;$("#saveResultBtn").disabled=true;$("#saveStatus").textContent="기록을 등록하고 있어요…";try{if(state.classCode===CONFIG.demoCode||!CONFIG.apiUrl)saveLocalResult();else{const d=await api("submitResult",{sessionId:state.sessionId,answers:state.answers});state.lastRankId=d.resultId}$("#saveStatus").textContent="기록이 등록됐어요!";setTimeout(showRanking,500)}catch(e){saveLocalResult();$("#saveStatus").textContent=`서버 연결 실패로 이 기기에 임시 저장했어요. (${e.message})`;$("#saveResultBtn").disabled=false}}
async function showRanking(){show("ranking");$("#rankingSubtitle").textContent=`${state.classTitle||state.classCode} 랭킹`;let rows;try{rows=state.classCode!==CONFIG.demoCode&&CONFIG.apiUrl?(await api("getRanking",{code:state.classCode})).rankings:localRankings().filter(x=>x.classCode===state.classCode)}catch{rows=localRankings().filter(x=>x.classCode===state.classCode)}rows.sort((a,b)=>b.correct-a.correct||a.timeMs-b.timeMs||a.createdAt.localeCompare(b.createdAt));$("#rankingList").innerHTML=rows.length?rows.slice(0,10).map((r,i)=>`<div class="rank-row ${r.id===state.lastRankId?"me":""}"><span class="position">${i+1}</span><span class="person"><b>${r.character||"🐲"}</b><span>${escapeText(r.name)}</span></span><strong>${formatTime(r.timeMs)}</strong><small class="accuracy">${r.correct}/${r.total} 정답</small></div>`).join(""):`<p class="sub">아직 등록된 기록이 없습니다.</p>`}

$("#enterBtn").addEventListener("click",enterClass);$("#classCode").addEventListener("keydown",e=>{if(e.key==="Enter")enterClass()});
$("#toCharactersBtn").addEventListener("click",()=>{const n=escapeText($("#studentName").value).trim();if(!n){$("#studentName").focus();return}state.studentName=n;renderCharacters();show("character")});
$("#characterGrid").addEventListener("click",e=>{const b=e.target.closest(".character-card");if(b)chooseCharacter(b.dataset.id)});$("#startGameBtn").addEventListener("click",startGame);$("#answers").addEventListener("click",e=>{const b=e.target.closest(".answer-btn");if(b)answerQuestion(Number(b.dataset.index))});$("#speakBtn").addEventListener("click",speak);$("#saveResultBtn").addEventListener("click",saveResult);$("#retryBtn").addEventListener("click",startGame);$("#rankBtn").addEventListener("click",showRanking);$("#rankPlayBtn").addEventListener("click",()=>show(state.studentName?"character":"start"));$("#homeBtn").addEventListener("click",()=>show("start"));$("#soundBtn").addEventListener("click",()=>{state.sound=!state.sound;$("#soundBtn").textContent=state.sound?"♪":"×"});$$(`[data-nav]`).forEach(b=>b.addEventListener("click",()=>show(b.dataset.nav)));
document.addEventListener("keydown",e=>{if(state.screen==="game"&&!state.locked&&["1","2","3","4"].includes(e.key))answerQuestion(Number(e.key)-1)});
renderCharacters();
